static char *changed(const char *input, const char *old, const char *replacement) {
    const char *found = strstr(input, old); assert(found);
    size_t left = (size_t)(found-input), oldn = strlen(old), newn = strlen(replacement);
    char *copy = malloc(strlen(input)-oldn+newn+1); assert(copy);
    memcpy(copy,input,left); memcpy(copy+left,replacement,newn);
    strcpy(copy+left+newn,found+oldn); return copy;
}
static void rejects(const char *old, const char *replacement) {
    char *copy = changed(valid_report,old,replacement);
    CHECK(sts_observation_parse_report(copy,strlen(copy),&config,&manifest,&report,error,sizeof(error)) != 0);
    free(copy);
}
