static void numeric_tests(void) {
    char maximal_id[129]; memset(maximal_id,'a',sizeof(maximal_id));
    CHECK(!sts_observation_id_valid(maximal_id)); maximal_id[128]=0;
    CHECK(sts_observation_id_valid(maximal_id));
    uint64_t value=17;
    CHECK(sts_observation_parse_decimal("0",UINT64_MAX,&value) && value==0);
    CHECK(sts_observation_parse_decimal("00090",100,&value) && value==90);
    CHECK(sts_observation_parse_decimal("18446744073709551615",UINT64_MAX,&value) && value==UINT64_MAX);
    const char *bad[] = {"", "+1", "-0", " 1", "1 ", "1\n", "0x10", "1e2", "NaN", "inf", "1KB", "1.0", "18446744073709551616", "999999999999999999999999999999999999999999"};
    for (size_t i=0;i<sizeof(bad)/sizeof(bad[0]);++i) CHECK(!sts_observation_parse_decimal(bad[i],UINT64_MAX,&value));
    CHECK(!sts_observation_parse_decimal(NULL,UINT64_MAX,&value));
    CHECK(!sts_observation_parse_decimal("101",100,&value));
    CHECK(sts_observation_coverage_pass(9,10,90));
    CHECK(!sts_observation_coverage_pass(8,10,90));
    CHECK(!sts_observation_coverage_pass(899,1000,90));
    CHECK(!sts_observation_coverage_pass(0,0,0));
    CHECK(!sts_observation_coverage_pass(2,1,0));
    CHECK(sts_observation_coverage_pass(UINT64_MAX,UINT64_MAX,100));
    CHECK(!sts_observation_coverage_pass(UINT64_MAX-1,UINT64_MAX,100));
    CHECK(sts_observation_coverage_pass(0,UINT64_MAX,0));
    uint64_t seed=UINT64_C(0x523fed84b99e271b);
    for (unsigned i=0;i<10000;++i) {
        seed=seed*UINT64_C(6364136223846793005)+1;
        uint64_t eligible=seed ? seed : 1;
        seed=seed*UINT64_C(6364136223846793005)+1;
        uint64_t covered=seed%eligible;
        uint32_t minimum=i%101;
        int expected=(__uint128_t)covered*100 >= (__uint128_t)eligible*minimum;
        CHECK(sts_observation_coverage_pass(covered,eligible,minimum)==expected);
    }
    char digest[129]; sts_observation_digest("abc",3,digest);
    CHECK(!strcmp(digest,"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"));
}
