    memset(&child,0,sizeof(child)); waits=0;wait_mode=1;
    CHECK(sts_observation_wait_child(123,&child,fake_wait)); CHECK(waits==1 && child.wait_errno==ECHILD);
    memset(&child,0,sizeof(child)); waits=0;wait_mode=2;
    CHECK(!sts_observation_wait_child(123,&child,fake_wait)); CHECK(child.signal==SIGTERM && !child.exited);
    char *args[]={"image",NULL},*env[]={NULL}; execs=0;
