    CHECK(!sts_observation_metadata_emit(f,&run,&config,&manifest,&child,&report,1,INT32_MAX));CHECK(!fclose(f));
    CHECK(size<=run.metadata_preflight_size&&size<STS_OBS_METADATA_LIMIT);
