    CHECK(strstr(json,"escaped\\u000a\\u0009\\\"\\\\\\u00ff"));
    char *domains=strstr(json,"\"allocation_domains\":");CHECK(domains);
    char *domain_end=strchr(domains,'\n');CHECK(domain_end&&(size_t)(domain_end-domains)==242u);
    char *rows=strstr(json,"\"allocations\":[");CHECK(rows);
