static char *mixed_raw(sts_observation_manifest *m,const char *records) {
    CHECK(!sts_observation_manifest_digest(&config,m));
    char *a=changed(valid_report,manifest.map_id,m->map_id);
    char *b=changed(a,"inventory 2 10 2","inventory 2 10 5");free(a);
    a=changed(b,"allocations 1 8\nallocation 1 1 8 0 1 0\nEND\n",records);free(b);return a;
}
static void mixed_domain_tests(void) {
    sts_observation_site ss[5]={sites[0],sites[1],sites[0],sites[0],sites[0]};
    ss[2].kind=STS_OBS_REM;ss[3].kind=STS_OBS_SLICE_MAKE;ss[4].kind=STS_OBS_SLICE_REM;
    ss[3].slice_element_kind=STS_OBS_SLICE_I32;ss[3].slice_abi_stride=4;ss[3].slice_count_arity=2;
    sts_observation_manifest m=manifest;m.sites=ss;m.site_count=5;
    const char *records="allocations 2 27\nallocation 1 1 7 0 4294967295 0\nallocation 2 2 20 3 4294967295 0\nEND\n";
    char *raw=mixed_raw(&m,records);CHECK(sts_observation_manifest_valid(&config,&m));
    CHECK(!sts_observation_parse_report(raw,strlen(raw),&config,&m,&report,error,sizeof(error)));
    CHECK(report.live_bytes==27&&report.live_count==2&&report.domain_bytes[0]==7&&report.domain_bytes[1]==20);
    CHECK(report.domain_counts[0]==1&&report.domain_counts[1]==1&&report.live[0].domain==1&&report.live[1].domain==2);
    sts_observation_child child={.launched=1,.waited=1,.exited=1};
    sts_observation_config c=config;c.max_bytes=27;CHECK(!sts_observation_status(&c,&m,&report,&child));
    c.max_bytes=26;CHECK(sts_observation_status(&c,&m,&report,&child));c.has_max_bytes=0;CHECK(!sts_observation_status(&c,&m,&report,&child));
    char *coverage=changed(raw,"enabled 3","enabled 2");c.warn_memleak=0;c.enabled_mask=2;
    CHECK(!sts_observation_parse_report(coverage,strlen(coverage),&c,&m,&report,error,sizeof(error)));
    CHECK(report.live_bytes==27&&report.domain_bytes[1]==20);free(coverage);
    const char *bad_rows[]={
        "allocation 2 0 20 3 4294967295 0","allocation 2 3 20 3 4294967295 0",
        "allocation 2 4294967295 20 3 4294967295 0","allocation 2 1 20 3 4294967295 0",
        "allocation 2 2 20 0 4294967295 0","allocation 2 2 20 4 4294967295 0",
        "allocation 2 2 20 3 1 0","allocation 2 2 0 3 4294967295 0",
        "allocation 2 2 21 3 4294967295 0","allocation 2 2 20 9 4294967295 0",
        "allocation 2 2 20 3 4294967295 2","allocation 1 2 20 3 4294967295 0",
        "allocation 0 2 20 3 4294967295 0","allocation 02 2 20 3 4294967295 0",
        "allocation 2 02 20 3 4294967295 0"};
    for(size_t i=0;i<sizeof(bad_rows)/sizeof(bad_rows[0]);++i){
        char *bad=changed(raw,"allocation 2 2 20 3 4294967295 0",bad_rows[i]);
        CHECK(sts_observation_parse_report(bad,strlen(bad),&config,&m,&report,error,sizeof(error))!=0);free(bad);
    }
    char *bad=changed(raw,"allocations 2 27","allocations 2 26");
    CHECK(sts_observation_parse_report(bad,strlen(bad),&config,&m,&report,error,sizeof(error))!=0);free(bad);
    bad=changed(raw,"allocation 1 1 7 0 4294967295 0","allocation 1 1 18446744073709551615 0 4294967295 0");
    CHECK(sts_observation_parse_report(bad,strlen(bad),&config,&m,&report,error,sizeof(error))!=0);free(bad);
    bad=changed(raw,"state 1 0 1","state 0 13 1");
    CHECK(!sts_observation_parse_report(bad,strlen(bad),&config,&m,&report,error,sizeof(error)));
    CHECK(sts_observation_status(&c,&m,&report,&child));free(bad);
    /* Parsed-only metadata, including coverage-only ledger results. */
    CHECK(!sts_observation_parse_report(raw,strlen(raw),&config,&m,&report,error,sizeof(error)));
    sts_observation_run run={.image_fd=-1};strcpy(run.target,"x86_64-unknown-linux-gnu");
    char *json=NULL;size_t size=0;FILE *f=open_memstream(&json,&size);CHECK(f);
    CHECK(!sts_observation_metadata_emit(f,&run,&c,&m,&child,&report,1,0));CHECK(!fclose(f));
    CHECK(strstr(json,"\"allocation_domains\":{\"explicit_user_heap\":{\"live_allocations\":1,\"tracked_outstanding_bytes\":7},\"generated_primitive_slice_backing\":{\"live_allocations\":1,\"tracked_outstanding_bytes\":20}}"));
    CHECK(strstr(json,"\"generation\":2,\"domain\":2,\"bytes\":20"));
    CHECK(strstr(json,"\"slice_element_kind\":5,\"slice_abi_stride\":4,\"slice_count_arity\":2"));
    CHECK(strstr(json,"\"slice_element_kind\":0,\"slice_abi_stride\":0,\"slice_count_arity\":0"));
    CHECK(strstr(json,"\"allocation_metric\":\"disabled\""));free(json);
    json=NULL;size=0;f=open_memstream(&json,&size);CHECK(f);
    CHECK(!sts_observation_metadata_emit(f,&run,&c,&m,&child,NULL,0,1));CHECK(!fclose(f));
    CHECK(!strstr(json,"\"allocation_domains\"")&&!strstr(json,"\"tracked_outstanding_bytes\""));free(json);free(raw);
    /* All allowed primitive enums and both count arities, with no native blocks. */
    const uint32_t strides[]={0,1,1,2,2,4,4,8,8,1,4,8};
    for(uint32_t element=1;element<=11;++element)for(uint32_t arity=1;arity<=2;++arity){
        ss[3].slice_element_kind=element;ss[3].slice_abi_stride=strides[element];ss[3].slice_count_arity=arity;
        uint64_t capacity[]={0,1,INT32_MAX,(uint64_t)INT32_MAX+1};
        for(unsigned k=0;k<4;++k){
            uint64_t bytes=capacity[k]*strides[element];char record[256];
            snprintf(record,sizeof(record),"allocations 1 %" PRIu64 "\nallocation 1 2 %" PRIu64 " 3 4294967295 0\nEND\n",bytes,bytes);
            raw=mixed_raw(&m,record);CHECK(sts_observation_manifest_valid(&config,&m));
            int parsed=sts_observation_parse_report(raw,strlen(raw),&config,&m,&report,error,sizeof(error));
            CHECK((parsed==0)==(k==1||k==2));free(raw);
        }
        if(strides[element]>1){
            char record[256];unsigned bytes=strides[element]+1;
            snprintf(record,sizeof(record),"allocations 1 %u\nallocation 1 2 %u 3 4294967295 0\nEND\n",bytes,bytes);
            raw=mixed_raw(&m,record);CHECK(sts_observation_parse_report(raw,strlen(raw),&config,&m,&report,error,sizeof(error))!=0);free(raw);
        }
    }
    ss[3].slice_element_kind=5;ss[3].slice_abi_stride=4;ss[3].slice_count_arity=2;
    uint32_t *fields[]={&ss[3].slice_element_kind,&ss[3].slice_abi_stride,&ss[3].slice_count_arity};
    for(unsigned field=0;field<3;++field)for(unsigned variant=0;variant<2;++variant){
        uint32_t old=*fields[field];*fields[field]=variant?UINT32_MAX:0;
        raw=mixed_raw(&m,records);CHECK(!sts_observation_manifest_valid(&config,&m));
        CHECK(sts_observation_parse_report(raw,strlen(raw),&config,&m,&report,error,sizeof(error))!=0);free(raw);*fields[field]=old;
    }
    ss[3].slice_abi_stride=8;raw=mixed_raw(&m,records);CHECK(!sts_observation_manifest_valid(&config,&m));free(raw);ss[3].slice_abi_stride=4;
    for(unsigned site=0;site<5;++site)if(site!=3){
        uint32_t *absent[]={&ss[site].slice_element_kind,&ss[site].slice_abi_stride,&ss[site].slice_count_arity};
        for(unsigned field=0;field<3;++field){*absent[field]=1;raw=mixed_raw(&m,records);CHECK(!sts_observation_manifest_valid(&config,&m));free(raw);*absent[field]=0;}
    }
    ss[4].kind=6;raw=mixed_raw(&m,records);CHECK(!sts_observation_manifest_valid(&config,&m));free(raw);
}

